/* =========================================================
   V5.2 — POSTER COMPOSITION / SCALE + HIERARCHY
   Fixes hero crop, increases commerce authority, strengthens
   proof micro-type, and lets artwork own the left canvas.
   Commerce JS intentionally untouched.
   ========================================================= */

/* Hero artwork gets more canvas authority without forcing a crop. */
.tjs-mv4-hero__product{
  width:104%;
  height:96%;
}
.tjs-mv4-hero__img{
  padding:clamp(10px,1.7vw,24px)!important;
  object-fit:contain;
}
