}
.tjs-mv4-hero__drop,
.tjs-mv4-hero__grid::before,
.tjs-mv4-hero__buy::before{
  font-size:9.5px!important;
  opacity:.72;
}

/* Never vertically centre an over-height buying stack: this was the
   source of the headline being clipped above the hero viewport. */
.tjs-mv4-hero__buy{
  justify-content:flex-start!important;
}

/* Stronger proof strip — still editorial, not feature cards. */
.tjs-mv4-trust__item{
  min-height:66px;
  padding:13px 12px 12px 38px!important;
}
.tjs-mv4-trust__item::before{
  left:8px!important;
  top:12px!important;
  width:22px;
  height:22px;
  display:grid;
  place-items:center;
  background:var(--tjs-yellow);
  color:var(--tjs-ink)!important;
  font-size:10px!important;
  line-height:1!important;
}
.tjs-mv4-trust__title{
  font-size:10px!important;
  line-height:1.05!important;
  letter-spacing:.025em!important;
}
.tjs-mv4-trust__copy{
  font-size:11px!important;
  line-height:1.32!important;
  margin-top:5px!important;
  max-width:24ch;
}

/* Micro type should remain compact but actually readable. */
.tjs-mv4-tier-head strong,
.tjs-mv4-tier-head small{
  font-size:10px!important;
}
.tjs-mv4-tier__kicker{font-size:9.5px!important}
.tjs-mv4-tier__value{font-size:11.5px!important}
.tjs-mv4-tier__save{font-size:10.5px!important;line-height:1.25!important}
.tjs-mv4-summary__label{font-size:8.5px!important}

@media(min-width:1024px){
  /* Give buying UI equal authority to the visual instead of a narrow
     ecommerce sidebar. Adjustable in Theme Editor. */
  .tjs-mv4-hero__grid{
    grid-template-columns:minmax(0,var(--tjs-hero-media-col,50%)) minmax(0,1fr)!important;
  }
  .tjs-mv4-hero__buy{
