  .tjs-mv4-trust__copy{font-size:10.5px!important;line-height:1.3!important}
}

/* =========================================================
   V5.3 — INTEGRATED POSTER HERO
   Four deliberate headline lines, softer media/commerce seam,
   tighter artwork relationship, reduced outer rounding.
   Commerce logic untouched.
   ========================================================= */

/* One canvas first: the grid belongs to the hero, not just the media half. */
.tjs-mv4-hero__grid{
  border-radius:var(--tjs-hero-radius,3px)!important;
  overflow:hidden;
  background:
    linear-gradient(rgba(17,17,17,var(--tjs-grid-alpha,.055)) 1px,transparent 1px),
    linear-gradient(90deg,rgba(17,17,17,var(--tjs-grid-alpha,.055)) 1px,transparent 1px),
    radial-gradient(circle at 37% 72%,color-mix(in srgb,var(--tjs-yellow) 10%,transparent),transparent 22%),
    var(--tjs-paper)!important;
  background-size:var(--tjs-grid-size,32px) var(--tjs-grid-size,32px),var(--tjs-grid-size,32px) var(--tjs-grid-size,32px),auto,auto!important;
}

/* Kill the hard split. Media is transparent; commerce fades onto the shared canvas. */
.tjs-mv4-hero__media{
  border-right:0!important;
  background:transparent!important;
}
.tjs-mv4-hero__buy{
  position:relative;
  z-index:3;
  background:linear-gradient(90deg,rgba(247,246,241,0) 0,rgba(247,246,241,.84) var(--tjs-hero-blend,36px),rgba(247,246,241,.98) calc(var(--tjs-hero-blend,36px) + 34px),var(--tjs-paper) 35%)!important;
  margin-left:calc(var(--tjs-hero-blend,36px) * -1);
  padding-left:calc(var(--tjs-desktop-buy-pad,38px) + var(--tjs-hero-blend,36px))!important;
}

/* Four lines are authored, not browser-wrapped. */
.tjs-mv4-hero__h1{
  text-wrap:balance;
  max-width:none!important;
}
.tjs-mv4-hero__h1 .tjs-mv5-hline{
  display:block!important;
  width:max-content!important;
  max-width:100%!important;
  white-space:nowrap!important;
  margin:0!important;
}
.tjs-mv4-hero__h1 .tjs-mv5-hline:nth-child(2){margin-top:-.01em!important}
.tjs-mv4-hero__h1 .tjs-mv5-hline:nth-child(3){margin-top:.015em!important}
.tjs-mv4-hero__h1 .tjs-mv5-hline:nth-child(4){margin-top:-.005em!important}

/* Highlighter behaves like a physical mark rather than a thin underline. */
.tjs-mv4-highlight::before{
  left:-.06em!important;
  right:-.08em!important;
  bottom:.045em!important;
  height:.27em!important;
  border-radius:1px!important;
  transform:scaleX(0) rotate(-1.2deg) skewX(-3deg)!important;
}
.is-visible .tjs-mv4-highlight::before,
.tjs-mv4-highlight.is-visible::before{
  transform:scaleX(1) rotate(-1.2deg) skewX(-3deg)!important;
}

/* Tighter artwork relationship: push the object up into the previously dead field. */
.tjs-mv4-hero__product{
  width:108%!important;
  height:100%!important;
  transform:translateY(var(--tjs-hero-product-y,-9%)) scale(var(--tjs-hero-product-scale,1.06))!important;
  transform-origin:center 44%!important;
}
.tjs-mv4-hero__img{padding:clamp(4px,1vw,14px)!important}
.tjs-mv4-hero__fallback{width:min(98%,760px)!important}
.tjs-mv4-hero__glow{opacity:.28!important;bottom:8%!important;height:13%!important}

/* Give the campaign metadata proper edge breathing room. */
.tjs-mv4-hero__drop{top:14px!important;left:16px!important;font-size:9px!important}
.tjs-mv4-hero__grid::before{left:16px!important;bottom:14px!important;font-size:9px!important}
.tjs-mv4-hero__grid::after{right:17px!important;top:15px!important}
.tjs-mv4-hero__buy::before{right:16px!important;bottom:14px!important}

@media(min-width:1024px){
  .tjs-mv4-hero__grid{
    min-height:var(--tjs-hero-desktop-height,590px)!important;
  }
  .tjs-mv4-hero__media{
    min-height:var(--tjs-hero-desktop-height,590px)!important;
  }
  .tjs-mv4-hero__buy{
    min-height:var(--tjs-hero-desktop-height,590px)!important;
    justify-content:center!important;
    padding-top:28px!important;
    padding-bottom:28px!important;
  }
  .tjs-mv4-hero__h1{
    font-size:clamp(48px,4.55vw,var(--tjs-desktop-h1,82px))!important;
    line-height:.79!important;
    margin:5px 0 16px!important;
  }
  /* Commerce moves closer to the statement: less empty poster gutter. */
  .tjs-mv4-hero__copy{margin-bottom:16px!important}
  .tjs-mv4-tier-head{margin-bottom:7px!important}
  .tjs-mv4-tiers{gap:7px!important}
  .tjs-mv4-summary{margin-top:10px!important}
  .tjs-mv4-cta{margin-top:11px!important}
  .tjs-mv4-trust{margin-top:11px!important}
}

/* Tablet/mobile stays intentionally stacked and does not inherit the desktop overlap. */
@media(min-width:750px) and (max-width:1023px){
  .tjs-mv4-hero__buy{
    margin-left:0!important;
    padding-left:clamp(26px,3vw,44px)!important;
    background:var(--tjs-paper)!important;
  }
}
@media(max-width:749px){
  .tjs-mv4-hero__grid{border-radius:0!important}
  .tjs-mv4-hero__buy{margin-left:0!important;padding-left:var(--tjs-mobile-buy-pad,14px)!important;background:var(--tjs-paper)!important}
  .tjs-mv4-hero__h1 .tjs-mv5-hline{white-space:nowrap!important;width:max-content!important}
  .tjs-mv4-hero__product{
    width:84%!important;
    height:86%!important;
    transform:translateY(-3%) scale(1)!important;
  }
}


/* =========================================================
   V5.4 — MANUAL DISPLAY COMPOSITION
   Every major display headline is authored line-by-line.
   No browser word-wrap, hyphenation or mid-word splitting.
   ========================================================= */
.tjs-mv5-manual-heading{
  overflow:visible;
  word-break:keep-all!important;
  overflow-wrap:normal!important;
  hyphens:none!important;
}
.tjs-mv5-manual-line{
  display:block!important;
  width:max-content;
  max-width:100%;
  white-space:nowrap!important;
  word-break:keep-all!important;
  overflow-wrap:normal!important;
  hyphens:none!important;
}

/* Hero: exactly four authored lines. */
.tjs-mv4-hero__h1 .tjs-mv5-manual-line{width:max-content!important;max-width:100%!important}

/* Dark value section: three physical poster lines, not BR-driven wrapping. */
.tjs-mv4-value__headline .tjs-mv5-manual-line{position:relative;z-index:2}
.tjs-mv4-value__headline.is-visible .tjs-mv5-manual-line{animation:tjsKineticLine 520ms var(--tjs-ease-premium) forwards}
.tjs-mv4-value__headline.is-visible .tjs-mv5-manual-line:nth-child(2){animation-delay:80ms}
.tjs-mv4-value__headline.is-visible .tjs-mv5-manual-line:nth-child(3){animation-delay:160ms}

/* Journey: three intentional lines. */
.tjs-mv4-journey__heading .tjs-mv5-manual-line + .tjs-mv5-manual-line{margin-top:-.035em}

/* Gift: four art-directed lines. Prevent EXPECTED. from ever splitting. */
.tjs-mv4-gift__heading .tjs-mv5-manual-line + .tjs-mv5-manual-line{margin-top:-.045em}

/* Final CTA: supports up to three intentional lines. */
.tjs-mv4-final__heading .tjs-mv5-manual-line{margin-left:auto;margin-right:auto}
.tjs-mv4-final__heading .tjs-mv5-manual-line + .tjs-mv5-manual-line{margin-top:-.045em}

@media(max-width:749px){
  /* Scale the full authored line rather than allowing a line to wrap. */
  .tjs-mv4-gift__heading{font-size:clamp(30px,10.1vw,42px)!important}
  .tjs-mv4-journey__heading{font-size:clamp(31px,10.2vw,42px)!important}
  .tjs-mv4-final__heading{font-size:clamp(48px,18vw,78px)!important}
  .tjs-mv4-value__headline{font-size:clamp(46px,14.5vw,64px)!important}
}

/* =========================================================
   V5.5 — MOBILE SLIDE TO UNLOCK
   iPhone-inspired drag interaction for the primary mobile CTA.
   Desktop CTA and all cart/variant behavior remain intact.
   ========================================================= */
.tjs-mv5-slide-unlock{display:none}

@keyframes tjsSlideSheen{
  0%{background-position:180% 50%}
  100%{background-position:-80% 50%}
}

@media(max-width:749px){
  .tjs-mv4-hero[data-mobile-slide-enabled="true"] .tjs-mv4-form>.tjs-mv4-cta{display:none!important}
  .tjs-mv4-hero[data-mobile-slide-enabled="true"] .tjs-mv5-slide-unlock{display:block}

  .tjs-mv5-slide-unlock{
    --slide-x:0px;
    --slide-p:0;
    --slide-label-opacity:1;
    position:relative;
    width:100%;
    height:var(--tjs-slide-h,60px);
    margin-top:10px;
    border:1px solid var(--tjs-ink);
    border-radius:3px;
    overflow:hidden;
    background:var(--tjs-ink);
    color:#FFFFFF;
    user-select:none;
    -webkit-user-select:none;
    touch-action:pan-y;
    isolation:isolate;
    cursor:default;
  }
  .tjs-mv5-slide-unlock__fill{
    position:absolute;
    inset:0;
    z-index:0;
    background:var(--tjs-yellow);
    transform:scaleX(var(--slide-p,0));
    transform-origin:left center;
    opacity:.20;
    transition:transform 80ms linear,opacity 180ms ease;
    pointer-events:none;
  }
  .tjs-mv5-slide-unlock__label{
    position:absolute;
    inset:0;
    z-index:1;
    display:grid;
    place-items:center;
    padding:0 calc(var(--tjs-slide-thumb,50px) + 18px);
    font-family:var(--tjs-micro,var(--tjs-condensed));
    font-size:10px;
    font-weight:900;
    line-height:1;
    letter-spacing:.12em;
    text-transform:uppercase;
    white-space:nowrap;
    opacity:var(--slide-label-opacity,1);
    transition:opacity 80ms linear,color 180ms ease;
    pointer-events:none;
  }
  .tjs-mv5-slide-unlock.has-shimmer:not(.is-dragging):not(.is-complete):not(.is-disabled) .tjs-mv5-slide-unlock__label{
    color:transparent;
    background:linear-gradient(100deg,#FFFFFF 0%,#FFFFFF 34%,var(--tjs-yellow) 48%,#FFFFFF 62%,#FFFFFF 100%);
    background-size:220% 100%;
    -webkit-background-clip:text;
    background-clip:text;
    animation:tjsSlideSheen 2.1s linear infinite;
  }
  .tjs-mv5-slide-unlock__thumb{
    position:absolute;
    z-index:3;
    left:4px;
    top:4px;
    width:var(--tjs-slide-thumb,50px);
    height:calc(100% - 8px);
    min-width:42px;
    display:grid;
    place-items:center;
    border-radius:1px;
    background:var(--tjs-yellow);
    color:var(--tjs-ink);
    box-shadow:0 0 0 1px rgba(255,255,255,.10),4px 0 0 rgba(255,255,255,.06);
    transform:translate3d(var(--slide-x,0px),0,0);
    transition:transform 240ms cubic-bezier(.22,.75,.18,1),background 160ms ease,color 160ms ease;
    cursor:grab;
    touch-action:none;
    will-change:transform;
  }
  .tjs-mv5-slide-unlock__thumb span{
    font-family:var(--tjs-display,Arial,sans-serif);
    font-size:21px;
    font-weight:900;
    line-height:1;
    transform:translateX(1px);
  }
  .tjs-mv5-slide-unlock.is-dragging .tjs-mv5-slide-unlock__thumb{
    transition:none;
    cursor:grabbing;
  }
  .tjs-mv5-slide-unlock.is-dragging .tjs-mv5-slide-unlock__fill{transition:none}
  .tjs-mv5-slide-unlock.is-returning .tjs-mv5-slide-unlock__thumb{transition:transform 260ms cubic-bezier(.2,.8,.2,1)}
  .tjs-mv5-slide-unlock.is-returning .tjs-mv5-slide-unlock__fill{transition:transform 260ms cubic-bezier(.2,.8,.2,1)}
  .tjs-mv5-slide-unlock.is-instant .tjs-mv5-slide-unlock__thumb,
  .tjs-mv5-slide-unlock.is-instant .tjs-mv5-slide-unlock__fill{transition:none!important}
  .tjs-mv5-slide-unlock.is-complete{
    border-color:var(--tjs-yellow);
  }
  .tjs-mv5-slide-unlock.is-complete .tjs-mv5-slide-unlock__fill{opacity:.94}
  .tjs-mv5-slide-unlock.is-complete .tjs-mv5-slide-unlock__label{color:var(--tjs-ink);opacity:1;font-weight:900}
  .tjs-mv5-slide-unlock.is-complete .tjs-mv5-slide-unlock__thumb{background:#FFFFFF;color:var(--tjs-ink)}
  .tjs-mv5-slide-unlock.is-disabled{
    opacity:.42;
    cursor:not-allowed;
  }
  .tjs-mv5-slide-unlock.is-disabled .tjs-mv5-slide-unlock__thumb{cursor:not-allowed;background:#F5F5F3}
  .tjs-mv5-slide-unlock:focus-visible{outline:3px solid var(--tjs-yellow);outline-offset:3px}
}

@media(prefers-reduced-motion:reduce){
  .tjs-mv5-slide-unlock.has-shimmer .tjs-mv5-slide-unlock__label{animation:none!important;color:#FFFFFF!important}
  .tjs-mv5-slide-unlock__thumb,.tjs-mv5-slide-unlock__fill{transition:none!important}
}

