june-glow.jglow{display:block;position:relative;isolation:isolate;max-width:1680px;margin:auto;background:var(--jglow-bg);color:var(--jglow-ink);padding:0 36px 28px}

.jglow *{box-sizing:border-box}.jglow [hidden]{display:none!important}.jglow h2,.jglow h3,.jglow p{margin:0;color:inherit}.jglow a{color:inherit;text-decoration:none}.jglow button{appearance:none;cursor:pointer;color:inherit}.jglow strong{font-weight:700}.jglow a:focus-visible,.jglow button:focus-visible{outline:3px solid var(--jglow-accent);outline-offset:5px}

.jglow .jglow__heading{font-family:var(--jglow-heading-font);font-size:var(--jglow-heading-size);font-weight:var(--jglow-heading-weight);letter-spacing:var(--jglow-heading-tracking);line-height:var(--jglow-heading-leading)}

.jglow .jglow__title{font-family:var(--jglow-title-font);font-size:var(--jglow-title-size);font-weight:var(--jglow-title-weight);letter-spacing:var(--jglow-title-tracking);line-height:var(--jglow-title-leading)}

.jglow .jglow__body{font-family:var(--jglow-body-font);font-size:var(--jglow-body-size);font-weight:var(--jglow-body-weight);letter-spacing:var(--jglow-body-tracking);line-height:var(--jglow-body-leading)}

.jglow .jglow__button-type{font-family:var(--jglow-button-font);font-size:var(--jglow-button-size);font-weight:var(--jglow-button-weight);letter-spacing:var(--jglow-button-tracking);line-height:var(--jglow-button-leading)}





.jglow__stage{position:relative;min-height:460px;margin:0 -36px}.jglow__scenes{position:absolute;inset:0;overflow:hidden}.jglow__scene{position:absolute;inset:0 0 0 43%;animation:jglow-in var(--jglow-duration) ease both}.jglow__scene picture,.jglow__scene img{display:block;width:100%;height:100%;object-fit:contain;object-position:center}.jglow__scene img{mask-image:linear-gradient(90deg,transparent,#000 12%,#000 88%,transparent)}.jglow__scene:after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,var(--jglow-bg),transparent 20%),linear-gradient(0deg,var(--jglow-bg),transparent 22%)}

.jglow__header{position:relative;z-index:1;width:57%;padding:64px 0 60px 60px;pointer-events:none}.jglow .jglow__heading{margin:20px 0 24px;overflow-wrap:break-word;text-shadow:0 2px 25px #17171766}.jglow__eyebrow{text-transform:uppercase;font-size:calc(var(--jglow-button-size)*.75)!important;letter-spacing:.15em!important}.jglow__header .jglow__body{max-width:350px}

.jglow__dock{position:relative;display:grid;grid-template-columns:1.5fr 1fr;gap:34px;background:#17171706;border:1px solid #DADADA50;border-radius:3px;padding:20px 26px}.jglow__selection{min-width:0}.jglow__nav{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin-top:10px}.jglow__choice{background:transparent;border:0;border-bottom:2px solid transparent;display:flex;align-items:center;justify-content:center;gap:14px;padding:8px 4px 14px;opacity:.65;min-height:88px;transition:opacity var(--jglow-duration) ease,border-color var(--jglow-duration) ease}.jglow__choice img{width:64px;height:64px;border-radius:50%;object-fit:cover}.jglow__choice span{overflow-wrap:anywhere}.jglow__choice[aria-pressed=true]{opacity:1;border-color:var(--jglow-accent)}.jglow__choice:hover{opacity:1}.jglow__details{border-left:1px solid #DADADA45;padding-left:34px;align-self:center}.jglow__product-heading{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin-bottom:14px}.jglow__product-heading .jglow__body{white-space:nowrap}.jglow__arrow{display:grid;place-items:center;width:32px;height:32px;flex:none;border-radius:50%;background:#171717;color:var(--jglow-accent)}.jglow__arrow svg{width:18px;height:18px}.jglow .jglow__primary{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:50px;padding:8px 9px 8px 22px;border:1px solid #171717;border-radius:999px;background:var(--jglow-accent);color:#171717;box-shadow:-2px 1px 0 #171717;transition:transform var(--jglow-duration) ease}.jglow .jglow__secondary{display:flex;align-items:center;justify-content:center;gap:8px;min-height:44px;text-decoration:underline;text-underline-offset:4px;margin-top:6px}.jglow__secondary .jglow__arrow{width:22px;height:22px}.jglow__secondary svg{width:14px;height:14px}

@keyframes jglow-in{from{opacity:0}to{opacity:1}}@media(hover:hover){.jglow[data-motion=true] .jglow__primary:hover{transform:translateY(-2px)}}

