@media(prefers-reduced-motion:reduce){.jglow *{animation:none!important;transition:none!important}.jglow .jglow__primary{transform:none!important}}.jglow[data-motion=false] *{animation:none!important;transition:none!important}




.jglow{scroll-margin-top:110px}.jglow__stage{min-height:0!important;height:390px!important;display:grid;grid-template-columns:1fr 1fr;gap:24px}.jglow__scenes{position:relative!important;inset:auto!important;grid-column:2;height:100%;width:100%!important}.jglow__header{position:relative!important;inset:auto!important;grid-column:1;grid-row:1;padding:50px 24px!important;max-width:none!important}.jglow__scene{height:100%;border:1px solid #DADADA33;border-radius:16px;overflow:hidden}.jglow__scene picture,.jglow__scene img{height:100%;width:100%;object-fit:contain!important;mask-image:none!important}.jglow__spec{margin:10px 0 16px!important}.jglow__choice{opacity:1!important}.jglow__choice img{object-fit:cover;object-position:50% 42%;border:1px solid #DADADA55}.jglow__dock{margin-top:20px!important}
