    {
      "type": "text",
      "id": "brand_name",
      "label": "Wordmark",
      "default": "The June Shop"
    },
    {
      "type": "text",
      "id": "tagline",
      "label": "Brand statement",
      "default": "For your plans."
    },
    {
      "type": "text",
      "id": "tagline_second",
      "label": "Brand statement second line",
      "default": "And everything around them."
    },
    {
      "type": "url",
      "id": "instagram",
      "label": "Instagram URL"
    },
    {
      "type": "text",
      "id": "instagram_label",
      "label": "Instagram desktop label",
      "default": "Find us on Instagram"
    },
    {
      "type": "text",
      "id": "mobile_instagram_label",
      "label": "Instagram mobile label",
      "default": "Instagram"
    },
    {
      "type": "text",
      "id": "back",
      "label": "Back to top label",
      "default": "Back to top"
    },
    {
      "type": "checkbox",
      "id": "newsletter",
      "label": "Show email signup disclosure",
      "default": true
    },
    {
      "type": "text",
      "id": "signup_heading",
      "label": "Signup disclosure label",
      "default": "Email updates"
    },
    {
      "type": "text",
      "id": "email_label",
      "label": "Email label",
      "default": "Email address"
    },
    {
      "type": "text",
      "id": "subscribe",
      "label": "Subscribe button",
      "default": "Subscribe"
    },
    {
      "type": "text",
      "id": "success",
      "label": "Signup success",
