.jt__choice{display:flex;align-items:center;width:100%;gap:14px;padding:18px 0;background:none;border:0;border-bottom:1px solid #17171733;text-align:left}.jt__number{opacity:.5}.jt__mark{margin-left:auto;opacity:0}.jt__choice[aria-pressed=true] .jt__mark{opacity:1}.jt__choice[aria-pressed=true] .jt__number{background:var(--jt-accent);opacity:1;color:#171717}.jt__number{border-radius:50%;width:30px;height:30px;display:grid;place-items:center;flex:none}.jt__products{padding-top:24px}.jt .jt__product-name{font-weight:700}.jt .jt__detail{margin-top:7px;opacity:.7;font-size:calc(var(--jt-body-size)*.85)}.jt .jt__price{margin-top:10px}.jt .jt__primary{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:52px;margin-top:22px;padding:9px 10px 9px 20px;border:1px solid #171717;border-radius:999px;background:var(--jt-accent);color:#171717;box-shadow:-2px 1px 0 #171717}.jt__arrow{display:grid;place-items:center;width:30px;height:30px;flex:none;border-radius:50%;background:#171717;color:var(--jt-accent)}.jt__arrow svg{width:18px;height:18px}.jt .jt__secondary{display:flex;gap:12px;align-items:center;justify-content:center;min-height:44px;margin-top:12px;text-decoration:underline;text-underline-offset:5px}.jt__secondary .jt__arrow,.jt__footer .jt__arrow{width:22px;height:22px}.jt__footer{border-top:1px solid #17171733;display:flex;justify-content:center;gap:48px;padding:16px 32px}.jt__footer a{display:flex;gap:14px;align-items:center;min-height:44px;text-decoration:underline;text-underline-offset:5px}
