.jh__browse{display:none}@media(max-width:749px){.jh__browse{display:block;border-bottom:1px solid #17171722;padding:0 18px;font-size:var(--jh-mobile-nav,13px);font-weight:500}.jh__browse summary{min-height:44px;display:flex;align-items:center;justify-content:space-between;cursor:pointer}.jh__browse summary:after{content:'+';font-size:20px}.jh__browse[open] summary:after{content:'−'}.jh__browse nav{display:grid;grid-template-columns:1fr 1fr;gap:0 16px;padding-bottom:10px}.jh__browse a{display:flex;justify-content:space-between;align-items:center;min-height:44px;color:inherit;text-decoration:underline;text-underline-offset:4px}.jh .jh__tab{font-size:var(--jh-mobile-nav,13px)!important}.jh .jh__mystery{font-size:var(--jh-mobile-nav,13px)!important}}

