tion.id }} .tjs-worlds__editorial{margin-top:32px;border-radius:18px}#TjsCollectionWorlds-{{ section.id }} .tjs-worlds__editorial-image{aspect-ratio:4/3}#TjsCollectionWorlds-{{ section.id }} .tjs-worlds__editorial-copy{left:12px;right:12px;bottom:12px;max-width:none;padding:13px}#TjsCollectionWorlds-{{ section.id }} .tjs-worlds__editorial-copy h3{font-size:24px}}
