      font-size: 7px;
      font-weight: 900;
      letter-spacing: .08em;
      text-transform: uppercase;
    }

    #TjsMystery-{{ section.id }} .tjs-selected-summary {
      display: grid;
      grid-template-columns: repeat(3,1fr);
      gap: 0;
      margin: 9px 0;
      border: 1px solid var(--line);
