  document.addEventListener("DOMContentLoaded", function () {
    const qtySelector = document.querySelector("[data-tjs-qty-selector]");
    if (!qtySelector) return;

    const minusBtn = qtySelector.querySelector("[data-tjs-qty-minus]");
    const plusBtn = qtySelector.querySelector("[data-tjs-qty-plus]");
    const qtyNumber = qtySelector.querySelector("[data-tjs-qty-number]");
    const giftNote = qtySelector.querySelector("[data-tjs-qty-gift-note]");

    const productForm =
      qtySelector.closest("section")?.querySelector('form[action*="/cart/add"]') ||
      document.querySelector('form[action*="/cart/add"]');

    if (!productForm) return;

    let formQtyInput = productForm.querySelector('input[name="quantity"]');

    if (!formQtyInput) {
      formQtyInput = document.createElement("input");
      formQtyInput.type = "hidden";
      formQtyInput.name = "quantity";
      productForm.appendChild(formQtyInput);
    }

    function getQty() {
      const currentQty = parseInt(formQtyInput.value, 10);
      return Number.isFinite(currentQty) && currentQty > 0 ? currentQty : 1;
    }

    function animateQty() {
      qtyNumber.classList.remove("tjs-qty-pop");
      void qtyNumber.offsetWidth;
      qtyNumber.classList.add("tjs-qty-pop");
