    const productHandle = "{{ product.handle }}";
    const favStorageKey = "tjs_favourite_" + productHandle;

    function syncFavouriteState() {
      if (localStorage.getItem(favStorageKey) === "true") {
        favBtn.classList.add("is-active");
        favBtn.setAttribute("aria-label", "Remove from favourites");
      } else {
        favBtn.classList.remove("is-active");
        favBtn.setAttribute("aria-label", "Add to favourites");
      }
    }

    syncFavouriteState();

    favBtn.addEventListener("click", function () {
      const isActive = favBtn.classList.contains("is-active");

      if (isActive) {
        localStorage.removeItem(favStorageKey);
      } else {
        localStorage.setItem(favStorageKey, "true");
      }

      syncFavouriteState();
    });

