  .tjs-main-character-section {
    margin: 36px 0;
    padding: 38px 18px;
    font-family: inherit;
    background:
      radial-gradient(circle at top left, rgba(255, 238, 231, 0.95), transparent 34%),
      radial-gradient(circle at bottom right, rgba(255, 247, 239, 0.95), transparent 34%),
      linear-gradient(135deg, #FFFFFF 0%, #FFFFFF 100%);
    border-radius: 30px;
    border: 1px solid rgba(23,23,23, 0.28);
    overflow: hidden;
  }

  .tjs-main-character-container {
    max-width: 1180px;
    margin: 0 auto;
  }

  .tjs-main-character-head {
    max-width: 760px;
    margin: 0 auto 28px;
    text-align: center;
  }

  .tjs-main-character-kicker {
    margin-bottom: 9px;
    font-size: 10.5px;
    line-height: 1;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    color: currentColor;
    font-weight: 850;
  }

  .tjs-main-character-title {
    margin: 0;
    font-size: clamp(28px, 3.2vw, 44px);
    line-height: 1.08;
    letter-spacing: -1px;
    color: #171717;
    font-weight: 850;
  }

  .tjs-main-character-title span {
    position: relative;
    display: inline-block;
    color: currentColor;
  }

  .tjs-main-character-title span::after {
    content: "";
    position: absolute;
    left: 0;
    bottom: 4px;
    width: 100%;
    height: 8px;
    border-radius: 999px;
    background: rgba(23,23,23, 0.65);
    z-index: -1;
  }

  .tjs-main-character-subtitle {
    max-width: 650px;
    margin: 13px auto 0;
    font-size: 14px;
    line-height: 1.7;
    color: #656565;
    font-weight: 500;
  }

  .tjs-main-character-tabs {
    display: flex;
    gap: 8px;
    justify-content: center;
    flex-wrap: wrap;
    margin: 0 auto 22px;
  }

  .tjs-main-character-tab {
    border: 1px solid rgba(23,23,23, 0.42);
    background: rgba(255, 255, 255, 0.74);
    color: #656565;
    padding: 10px 14px;
    border-radius: 999px;
    font-size: 12px;
    line-height: 1;
    font-weight: 800;
    cursor: pointer;
    transition: all 0.22s ease;
    font-family: inherit;
  }

  .tjs-main-character-tab:hover {
    transform: translateY(-1px);
    border-color: rgba(23,23,23, 0.42);
    color: #171717;
    box-shadow: 0 8px 18px rgba(47, 36, 32, 0.06);
  }

  .tjs-main-character-tab.is-active {
    background: linear-gradient(135deg, #171717, #F5F5F3);
    color: #FFFFFF;
    border-color: #171717;
    box-shadow: 0 9px 20px rgba(47, 36, 32, 0.14);
  }

  .tjs-main-character-layout {
    display: grid;
    grid-template-columns: 0.86fr 1.14fr;
    gap: 22px;
    align-items: stretch;
  }

  .tjs-main-character-visual {
    position: relative;
    overflow: hidden;
    min-height: 470px;
    border-radius: 26px;
    background: #FFFFFF;
    border: 1px solid rgba(23,23,23, 0.35);
    box-shadow: 0 14px 30px rgba(47, 36, 32, 0.06);
  }

  .tjs-main-character-image {
    width: 100%;
    height: 100%;
    min-height: 470px;
    display: block;
    object-fit: cover;
    object-position: center;
  }

  .tjs-main-character-panel {
    position: relative;
    overflow: hidden;
    border-radius: 26px;
    background: rgba(255, 255, 255, 0.78);
    border: 1px solid rgba(23,23,23, 0.34);
    box-shadow: 0 14px 30px rgba(47, 36, 32, 0.055);
    padding: 24px;
  }

  .tjs-main-character-panel::before {
    content: "";
    position: absolute;
    top: -75%;
    left: -35%;
    width: 86px;
    height: 240%;
    background: linear-gradient(110deg, transparent, rgba(255, 255, 255, 0.68), transparent);
    transform: rotate(18deg);
    animation: tjsMcSheen 6s ease-in-out infinite;
    pointer-events: none;
  }

  @keyframes tjsMcSheen {
    0% { left: -40%; opacity: 0; }
    14% { opacity: 0.7; }
    32%, 100% { left: 115%; opacity: 0; }
  }

  .tjs-main-character-pane {
    display: none;
    position: relative;
    z-index: 1;
  }

  .tjs-main-character-pane.is-active {
    display: block;
    animation: tjsMcPaneReveal 0.28s ease;
  }

  @keyframes tjsMcPaneReveal {
    from { opacity: 0; transform: translateY(5px); }
    to { opacity: 1; transform: translateY(0); }
  }

  .tjs-main-character-pane-head {
    display: flex;
    align-items: center;
    gap: 13px;
    margin-bottom: 18px;
  }

  .tjs-main-character-pane-icon {
    width: 46px;
    height: 46px;
    min-width: 46px;
    border-radius: 50%;
    display: grid;
    place-items: center;
    background: linear-gradient(135deg, #171717, #F5F5F3);
    color: currentColor;
    box-shadow: 0 9px 18px rgba(47, 36, 32, 0.14);
  }

  .tjs-main-character-pane-icon svg {
    width: 22px;
    height: 22px;
    stroke: currentColor;
    stroke-width: 1.9;
    fill: none;
    stroke-linecap: round;
    stroke-linejoin: round;
  }

  .tjs-main-character-pane-title {
    margin: 0;
    font-size: 24px;
    line-height: 1.1;
    letter-spacing: -0.5px;
    color: #171717;
    font-weight: 850;
  }

  .tjs-main-character-pane-subtitle {
    margin-top: 5px;
    font-size: 13px;
    line-height: 1.5;
    color: #656565;
    font-weight: 500;
  }

  .tjs-main-character-list {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 9px;
  }

  .tjs-main-character-item {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    padding: 11px;
    border-radius: 15px;
    background: #FFFFFF;
    border: 1px solid rgba(23,23,23, 0.28);
    color: #171717;
    font-size: 12.5px;
    line-height: 1.35;
    font-weight: 700;
  }

  .tjs-main-character-item::before {
    content: "✦";
    color: currentColor;
    font-size: 9px;
    line-height: 1.7;
    flex-shrink: 0;
  }

  .tjs-main-character-foot {
    margin-top: 16px;
    padding-top: 15px;
    border-top: 1px solid rgba(23,23,23, 0.3);
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
  }

  .tjs-main-character-pill {
    padding: 7px 10px;
    border-radius: 999px;
    background: rgba(255, 244, 239, 0.92);
    border: 1px solid rgba(23,23,23, 0.34);
    color: currentColor;
    font-size: 10.5px;
    line-height: 1;
    font-weight: 850;
  }

  @media screen and (max-width: 989px) {
    .tjs-main-character-layout {
      grid-template-columns: 1fr;
    }

    .tjs-main-character-visual,
    .tjs-main-character-image {
      min-height: 360px;
    }
  }

  @media screen and (max-width: 749px) {
    .tjs-main-character-section {
      margin: 28px -4px;
      padding: 28px 12px;
      border-radius: 24px;
    }

    .tjs-main-character-head {
      margin-bottom: 20px;
