      max-width: 94%;
    }

    .tjs-main-character-tabs {
      justify-content: flex-start;
      flex-wrap: nowrap;
      overflow-x: auto;
      padding: 2px 2px 8px;
      margin-bottom: 14px;
      scrollbar-width: none;
      -webkit-overflow-scrolling: touch;
    }

    .tjs-main-character-tabs::-webkit-scrollbar {
      display: none;
    }

    .tjs-main-character-tab {
      flex: 0 0 auto;
      font-size: 11px;
      padding: 10px 12px;
    }

    .tjs-main-character-layout {
      gap: 14px;
    }

    .tjs-main-character-visual {
      border-radius: 22px;
      min-height: 250px;
    }

    .tjs-main-character-image {
      min-height: 250px;
      border-radius: 22px;
    }

    .tjs-main-character-panel {
      padding: 16px;
      border-radius: 22px;
    }

    .tjs-main-character-pane-head {
      flex-direction: column;
      text-align: center;
      gap: 10px;
      margin-bottom: 15px;
    }

    .tjs-main-character-pane-icon {
      width: 42px;
      height: 42px;
      min-width: 42px;
    }

    .tjs-main-character-pane-icon svg {
      width: 20px;
      height: 20px;
    }

    .tjs-main-character-pane-title {
      font-size: 21px;
    }

    .tjs-main-character-pane-subtitle {
      font-size: 12.2px;
    }

    .tjs-main-character-list {
      grid-template-columns: 1fr;
      gap: 8px;
    }

    .tjs-main-character-item {
      padding: 10px 11px;
      font-size: 12px;
    }

    .tjs-main-character-foot {
      justify-content: center;
    }
  }
</style>

