<script>
  document.addEventListener("DOMContentLoaded", function () {
    const section = document.querySelector("[data-tjs-main-character]");
    if (!section) return;

    const tabs = section.querySelectorAll("[data-tjs-mc-tab]");
    const panes = section.querySelectorAll("[data-tjs-mc-pane]");

    tabs.forEach(function (tab) {
      tab.addEventListener("click", function () {
        const target = tab.getAttribute("data-tjs-mc-tab");

        tabs.forEach(function (item) {
          item.classList.remove("is-active");
        });

        panes.forEach(function (pane) {
          pane.classList.remove("is-active");
        });

        tab.classList.add("is-active");

        const activePane = section.querySelector('[data-tjs-mc-pane="' + target + '"]');
        if (activePane) {
          activePane.classList.add("is-active");
        }
      });
    });
  });
