<script>
  (function () {
    function activateUndatedHeroBg() {
      var marker = document.querySelector(".tjs-undated-hero-bg-marker");
      if (!marker) return;

      var target =
        marker.closest(".shopify-section") ||
        marker.closest("[id*='main-product']") ||
        marker.closest("section") ||
        document.querySelector("[id$='__main-product']") ||
        document.querySelector("#MainContent");

      if (target) {
        target.classList.add("tjs-undated-hero-active");
      }
    }

    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", activateUndatedHeroBg);
    } else {
      activateUndatedHeroBg();
    }
  })();
