<script>
  document.addEventListener("DOMContentLoaded", function () {
    const section = document.querySelector("[data-tjs-price-section]");
    if (!section) return;

    const productData = JSON.parse(section.getAttribute("data-product-json"));
    const currentPriceEl = section.querySelector("[data-tjs-current-price]");
    const comparePriceEl = section.querySelector("[data-tjs-compare-price]");
    const discountBadgeEl = section.querySelector("[data-tjs-discount-badge]");
    const saveLineEl = section.querySelector("[data-tjs-save-line]");

    function formatMoney(cents) {
      const amount = cents / 100;

      return "₹ " + new Intl.NumberFormat("en-IN", {
        maximumFractionDigits: 0
      }).format(amount);
    }

    function triggerPriceEffect() {
      currentPriceEl.classList.remove("tjs-price-pop");
      void currentPriceEl.offsetWidth;
      currentPriceEl.classList.add("tjs-price-pop");
    }

    function updatePrice(variant) {
      if (!variant) return;

      const price = variant.price;
      const comparePrice = variant.compare_at_price;

      currentPriceEl.textContent = formatMoney(price);
      triggerPriceEffect();

      if (comparePrice && comparePrice > price) {
        const saveAmount = comparePrice - price;
        const discountPercent = Math.round((saveAmount * 100) / comparePrice);

        comparePriceEl.style.display = "";
        discountBadgeEl.style.display = "";
        saveLineEl.style.display = "";

        comparePriceEl.textContent = formatMoney(comparePrice);
        discountBadgeEl.textContent = discountPercent + "% Off";
        saveLineEl.innerHTML = 'Your planning upgrade saves you <strong>' + formatMoney(saveAmount) + '</strong>';
      } else {
        comparePriceEl.style.display = "none";
        discountBadgeEl.style.display = "none";
        saveLineEl.style.display = "none";
      }
    }

    function getSelectedOptions() {
      const selectedOptions = [];

      document.querySelectorAll('input[type="radio"]:checked, select').forEach(function (input) {
        if (input.name && input.name.includes("options")) {
          selectedOptions.push(input.value);
        }
      });

      return selectedOptions;
    }

    function findVariantByOptions() {
      const selectedOptions = getSelectedOptions();

      return productData.variants.find(function (variant) {
        return variant.options.every(function (option, index) {
          return option === selectedOptions[index];
        });
      });
    }

    document.addEventListener("change", function () {
      setTimeout(function () {
        const selectedVariant = findVariantByOptions();
        updatePrice(selectedVariant);
      }, 100);
    });
  });
</script>"
