<script>
(function(){
  var btn = document.getElementById('tjs-mini-btn');
  var priceEl = document.getElementById('tjs-mini-live');
  var oldPriceEl = document.getElementById('tjs-mini-old');
  var note = document.getElementById('tjs-mini-note');

  if(!btn || !priceEl) return;

  var original = parseInt(priceEl.getAttribute('data-original'), 10);
  var discounted = Math.round(original / 2);

  function formatMoney(cents){
    return 'Rs. ' + Math.round(cents / 100).toLocaleString('en-IN');
  }

  function animatePrice(start, end, duration){
    var startTime = null;

    function step(timestamp){
      if(!startTime) startTime = timestamp;
      var progress = Math.min((timestamp - startTime) / duration, 1);
      var eased = 1 - Math.pow(1 - progress, 3);
      var current = Math.round(start + (end - start) * eased);

      priceEl.innerText = formatMoney(current);

      if(progress < 1){
        requestAnimationFrame(step);
      } else {
        priceEl.innerText = formatMoney(end);
        priceEl.classList.add('tjs-mini-pop');
        setTimeout(function(){
          priceEl.classList.remove('tjs-mini-pop');
        },400);
      }
    }

    requestAnimationFrame(step);
  }

  btn.addEventListener('click', function(){

    if(btn.classList.contains('claimed')) return;

    animatePrice(original, discounted, 700);

    // show original slashed AFTER click
    if(oldPriceEl){
      oldPriceEl.style.display = 'block';
    }

    btn.classList.add('claimed');
    btn.innerText = 'Deal Price Revealed ✓';

    if(note){
      note.innerText = 'Add to cart — 50% off applies automatically.';
    }
  });
})();
