<script>
  document.addEventListener("DOMContentLoaded", function () {
    const atcWrap = document.querySelector("[data-tjs-wedding-atc-wrap]");
    if (!atcWrap) return;

    const customAtcBtn = atcWrap.querySelector("[data-tjs-wedding-custom-atc]");
    const favBtn = atcWrap.querySelector("[data-tjs-wedding-fav-btn]");

    const productForm =
      atcWrap.closest("section")?.querySelector('form[action*="/cart/add"]') ||
      document.querySelector('form[action*="/cart/add"]');

    if (!productForm) return;

    const productHandle = "{{ product.handle }}";
    const favStorageKey = "tjs_wedding_favourite_" + productHandle;

    function syncFavouriteState() {
      if (localStorage.getItem(favStorageKey) === "true") {
        favBtn.classList.add("is-active");
        favBtn.setAttribute("aria-label", "Remove wedding planner from favourites");
      } else {
        favBtn.classList.remove("is-active");
        favBtn.setAttribute("aria-label", "Save this wedding planner");
      }
    }

    syncFavouriteState();

    favBtn.addEventListener("click", function () {
      const isActive = favBtn.classList.contains("is-active");

      if (isActive) {
        localStorage.removeItem(favStorageKey);
      } else {
        localStorage.setItem(favStorageKey, "true");
      }

      syncFavouriteState();
    });

    customAtcBtn.addEventListener("click", function () {
      customAtcBtn.classList.add("is-loading");

      const nativeSubmit =
        productForm.querySelector('[type="submit"]') ||
        productForm.querySelector('button[name="add"]');

      if (nativeSubmit) {
        nativeSubmit.click();
      } else {
        productForm.requestSubmit();
      }

      setTimeout(function () {
        customAtcBtn.classList.remove("is-loading");
      }, 1400);
    });
  });
</script>"
