<script>
  document.addEventListener("DOMContentLoaded", function () {
    const section = document.querySelector("[data-tjs-wedding-planning]");
    if (!section) return;

    const tabs = section.querySelectorAll("[data-tjs-wp-tab]");
    const panes = section.querySelectorAll("[data-tjs-wp-pane]");

    tabs.forEach(function (tab) {
      tab.addEventListener("click", function () {
        const target = tab.getAttribute("data-tjs-wp-tab");

        tabs.forEach(function (item) {
          item.classList.remove("is-active");
        });

        panes.forEach(function (pane) {
          pane.classList.remove("is-active");
        });

        tab.classList.add("is-active");

        const activePane = section.querySelector('[data-tjs-wp-pane="' + target + '"]');
        if (activePane) {
          activePane.classList.add("is-active");
        }
      });
    });
  });
</script>",
