<script>
  (function () {
    function initTjsVariantPicker() {
      var picker = document.querySelector("[data-tjs-variant-picker]");
      var variantsJson = document.querySelector("[data-tjs-product-variants]");

      if (!picker || !variantsJson) return;

      var variants = [];

      try {
        variants = JSON.parse(variantsJson.textContent);
      } catch (e) {
        return;
      }

      var availableVariants = variants.filter(function (variant) {
        return variant.available;
      });

      if (!availableVariants.length) {
        picker.style.display = "none";
        return;
      }

      var selectedOptions = availableVariants[0].options.slice();

      picker.querySelectorAll("[data-option-button].is-active").forEach(function (button) {
        var index = Number(button.getAttribute("data-option-index"));
        var value = button.getAttribute("data-option-value");

        var activeAvailable = availableVariants.some(function (variant) {
          return variant.options[index] === value;
        });

        if (activeAvailable) {
          selectedOptions[index] = value;
        }
      });

      function findVariantByOptions(options) {
        return availableVariants.find(function (variant) {
          return variant.options.every(function (optionValue, index) {
            return options[index] === optionValue;
          });
        });
      }

      function canOptionValueExist(optionIndex, optionValue) {
        var testOptions = selectedOptions.slice();
        testOptions[optionIndex] = optionValue;

        return availableVariants.some(function (variant) {
          return variant.options.every(function (variantOption, index) {
            return index === optionIndex || !testOptions[index] || testOptions[index] === variantOption;
          }) && variant.options[optionIndex] === optionValue;
        });
      }

      function findFirstAvailableForOption(optionIndex, optionValue) {
        return availableVariants.find(function (variant) {
          return variant.options[optionIndex] === optionValue;
        });
      }

      function updateSelectedLabels() {
        selectedOptions.forEach(function (value, index) {
          var label = picker.querySelector('[data-selected-label="' + index + '"]');
          if (label) label.textContent = value;
        });
      }

      function updateButtons() {
        picker.querySelectorAll("[data-option-button]").forEach(function (button) {
          var optionIndex = Number(button.getAttribute("data-option-index"));
          var optionValue = button.getAttribute("data-option-value");
          var canExist = canOptionValueExist(optionIndex, optionValue);

          button.classList.toggle("is-hidden", !canExist);
          button.classList.toggle("is-active", selectedOptions[optionIndex] === optionValue);
        });
      }

      function ensureValidVariant() {
        var variant = findVariantByOptions(selectedOptions);

        if (variant) return variant;

        var fallback = availableVariants[0];
        selectedOptions = fallback.options.slice();
        return fallback;
      }

      function updateHiddenVariantInput(variant) {
        if (!variant) return;

        document.querySelectorAll('form[action*="/cart/add"]').forEach(function (form) {
          var idInput = form.querySelector('[name="id"]');

          if (idInput) {
            idInput.value = variant.id;
            idInput.dispatchEvent(new Event("change", { bubbles: true }));
          }
        });
      }

      function updateUrl(variant) {
        if (!variant || !window.history || !window.history.replaceState) return;

        var url = new URL(window.location.href);
        url.searchParams.set("variant", variant.id);
        window.history.replaceState({}, "", url.toString());
      }

      function updateAddButtons(variant) {
        if (!variant) return;

        var submitButtons = document.querySelectorAll(
          'form[action*="/cart/add"] button[type="submit"], form[action*="/cart/add"] [name="add"], .product-form__submit'
        );

        submitButtons.forEach(function (button) {
          button.disabled = !variant.available;
        });
      }

      function dispatchVariantChange(variant) {
        if (!variant) return;

        document.dispatchEvent(new CustomEvent("variant:change", {
          bubbles: true,
          detail: {
            variant: variant
          }
        }));
      }

      function updatePicker() {
        var variant = ensureValidVariant();

        updateSelectedLabels();
        updateButtons();
        updateHiddenVariantInput(variant);
        updateUrl(variant);
        updateAddButtons(variant);
        dispatchVariantChange(variant);
      }

      picker.addEventListener("click", function (event) {
        var button = event.target.closest("[data-option-button]");
        if (!button || button.classList.contains("is-hidden")) return;

        var optionIndex = Number(button.getAttribute("data-option-index"));
        var optionValue = button.getAttribute("data-option-value");

        selectedOptions[optionIndex] = optionValue;

        var exactVariant = findVariantByOptions(selectedOptions);

        if (!exactVariant) {
          var fallback = findFirstAvailableForOption(optionIndex, optionValue);
          if (fallback) selectedOptions = fallback.options.slice();
        }

        updatePicker();
      });

      updatePicker();
    }

    document.addEventListener("DOMContentLoaded", initTjsVariantPicker);
    document.addEventListener("shopify:section:load", initTjsVariantPicker);
  })();
</script>"
