<script>
  (function () {
    function initTjsQtySelector() {
      var selector = document.querySelector("[data-tjs-qty-selector]");
      if (!selector) return;

      var input = selector.querySelector("[data-tjs-qty-input]");
      var minus = selector.querySelector("[data-tjs-qty-minus]");
      var plus = selector.querySelector("[data-tjs-qty-plus]");

      if (!input || !minus || !plus) return;

      function getThemeQuantityInputs() {
        return document.querySelectorAll('form[action*="/cart/add"] [name="quantity"]');
      }

      function syncThemeQuantity(value) {
        getThemeQuantityInputs().forEach(function (themeInput) {
          themeInput.value = value;
          themeInput.dispatchEvent(new Event("change", { bubbles: true }));
          themeInput.dispatchEvent(new Event("input", { bubbles: true }));
        });
      }

      function cleanValue(value) {
        var number = parseInt(value, 10);
        if (isNaN(number) || number < 1) number = 1;
        return number;
      }

      function setQty(value) {
        var finalValue = cleanValue(value);
        input.value = finalValue;
        syncThemeQuantity(finalValue);
        minus.disabled = finalValue <= 1;
      }

      minus.addEventListener("click", function () {
        setQty(cleanValue(input.value) - 1);
      });

      plus.addEventListener("click", function () {
        setQty(cleanValue(input.value) + 1);
      });

      input.addEventListener("change", function () {
        setQty(input.value);
      });

      input.addEventListener("input", function () {
        setQty(input.value);
      });

      setQty(input.value);
    }

    document.addEventListener("DOMContentLoaded", initTjsQtySelector);
    document.addEventListener("shopify:section:load", initTjsQtySelector);
  })();
