  (function () {
    function initTjsWhatsAppAssist() {
      var section = document.querySelector("[data-tjs-wa-assist]");
      if (!section) return;

      var title = section.querySelector("[data-tjs-wa-title]");
      var text = section.querySelector("[data-tjs-wa-text]");
      var cta = section.querySelector("[data-tjs-wa-cta]");
      var trust = section.querySelector("[data-tjs-wa-trust]");

      function getISTHour() {
        var parts = new Intl.DateTimeFormat("en-IN", {
          timeZone: "Asia/Kolkata",
          hour: "numeric",
          hour12: false
        }).formatToParts(new Date());

        var hourPart = parts.find(function (part) {
          return part.type === "hour";
        });

        return hourPart ? Number(hourPart.value) : new Date().getHours();
      }

      var hour = getISTHour();
      var isLive = hour >= 9 && hour < 18;

      section.classList.toggle("is-live", isLive);

      if (isLive) {
        if (title) title.textContent = "Need quick help before you order?";
        if (text) text.textContent = "Chat with us for product details, delivery timelines, offers or bulk gifting.";
        if (cta) cta.textContent = "Chat On WhatsApp →";
        if (trust) trust.innerHTML = "Usually replies faster during <strong>9 AM–6 PM.</strong>";
      } else {
        if (title) title.textContent = "Need help with this product?";
        if (text) text.textContent = "Leave us a WhatsApp message and our team will get back during working hours.";
        if (cta) cta.textContent = "Message Us →";
        if (trust) trust.innerHTML = "Support hours: <strong>9 AM–6 PM.</strong> You can still message us anytime.";
      }
    }

    document.addEventListener("DOMContentLoaded", initTjsWhatsAppAssist);
    document.addEventListener("shopify:section:load", initTjsWhatsAppAssist);
  })();
</script>"
