<script>
  (function () {
    function initTjsCustomAtc() {
      var row = document.querySelector("[data-tjs-atc-row]");
      if (!row) return;

      var customAtc = row.querySelector("[data-tjs-custom-atc]");
      var customAtcText = row.querySelector("[data-tjs-custom-atc-text]");
      var wishlist = row.querySelector("[data-tjs-custom-wishlist]");

      if (!customAtc) return;

      function findRealAddButton() {
        var buttons = Array.from(document.querySelectorAll(
          'form[action*="/cart/add"] button[type="submit"], form[action*="/cart/add"] [name="add"], .product-form__submit, [data-add-to-cart]'
        ));

        return buttons.find(function (button) {
          return button !== customAtc && !button.disabled && button.offsetParent !== null;
        }) || buttons.find(function (button) {
          return button !== customAtc && !button.disabled;
        });
      }

      function syncDisabledState() {
        var realButton = findRealAddButton();
        customAtc.disabled = !realButton;

        if (!realButton) {
          customAtcText.textContent = "Unavailable";
        } else if (!customAtc.classList.contains("is-loading")) {
          customAtcText.textContent = "Add To Cart";
        }
      }

      customAtc.addEventListener("click", function () {
        var realButton = findRealAddButton();

        if (!realButton) {
          customAtcText.textContent = "Select Option";
          setTimeout(syncDisabledState, 1200);
          return;
        }

        customAtc.classList.add("is-loading");
        customAtcText.textContent = "Adding...";

        realButton.click();

        setTimeout(function () {
          customAtcText.textContent = "Added ✓";
        }, 450);

        setTimeout(function () {
          customAtc.classList.remove("is-loading");
          customAtcText.textContent = "Add To Cart";
        }, 1500);
      });

      if (wishlist) {
        wishlist.addEventListener("click", function () {
          var realWishlist =
            document.querySelector('[data-wishlist-add]') ||
            document.querySelector('[data-wishlist-button]') ||
            document.querySelector('.wishlist-button') ||
            document.querySelector('.tinvwl_add_to_wishlist_button') ||
            document.querySelector('[aria-label*="Wishlist"]') ||
            document.querySelector('[aria-label*="wishlist"]');

          if (realWishlist && realWishlist !== wishlist && typeof realWishlist.click === "function") {
            realWishlist.click();
          }

          wishlist.classList.toggle("is-active");
          wishlist.setAttribute(
            "aria-label",
            wishlist.classList.contains("is-active") ? "Remove from wishlist" : "Add to wishlist"
          );
        });
      }

      document.addEventListener("variant:change", function () {
        setTimeout(syncDisabledState, 120);
      });

      document.addEventListener("change", function (event) {
        if (
          event.target.matches('[name="id"]') ||
          event.target.matches('input[type="radio"]') ||
          event.target.matches("select")
        ) {
          setTimeout(syncDisabledState, 120);
        }
      });

      syncDisabledState();
    }

    document.addEventListener("DOMContentLoaded", initTjsCustomAtc);
    document.addEventListener("shopify:section:load", initTjsCustomAtc);
  })();
</script>"
