<script>
  (function () {
    function initTjsProductTabs() {
      var section = document.querySelector("[data-tjs-product-tabs]");
      if (!section) return;

      var buttons = section.querySelectorAll("[data-tjs-tab-button]");
      var panels = section.querySelectorAll("[data-tjs-tab-panel]");
      var mobileHeads = section.querySelectorAll("[data-tjs-mobile-tab]");

      buttons.forEach(function (button) {
        button.addEventListener("click", function () {
          var target = button.getAttribute("data-tab");

          buttons.forEach(function (btn) {
            btn.classList.toggle("is-active", btn === button);
          });

          panels.forEach(function (panel) {
            panel.classList.toggle("is-active", panel.getAttribute("data-panel") === target);
          });
        });
      });

      mobileHeads.forEach(function (head) {
        head.addEventListener("click", function () {
          var panel = head.closest("[data-tjs-tab-panel]");
          if (!panel) return;

          panels.forEach(function (item) {
            if (item !== panel) item.classList.remove("is-mobile-open");
          });

          panel.classList.toggle("is-mobile-open");
        });
      });
    }

    document.addEventListener("DOMContentLoaded", initTjsProductTabs);
    document.addEventListener("shopify:section:load", initTjsProductTabs);
  })();
</script>",
